<?php
namespace App\Modules\CashManagement\Application;
use App\Models\User;use App\Modules\CashManagement\Domain\Models\CashTransfer;use App\Modules\Finance\Application\Data\JournalEntryData;use App\Modules\Finance\Application\Data\JournalLineData;use App\Modules\Finance\Application\PostJournalEntry;use App\Modules\Finance\Domain\Enums\FinancialDocumentStatus;use App\Modules\Finance\Domain\Models\FinancialAccount;use App\Modules\Shared\Application\NextDocumentNumber;use Carbon\CarbonInterface;use DomainException;use Illuminate\Support\Facades\DB;
class TransferCash {public function __construct(private readonly NextDocumentNumber $numbers,private readonly PostJournalEntry $journal,private readonly FinancialAccountBalance $balances){}public function execute(string $fromId,string $toId,int $amount,CarbonInterface $at,string $reason,User $actor):CashTransfer{if($fromId===$toId||$amount<=0||trim($reason)==='')throw new DomainException('El traslado requiere cuentas diferentes, valor positivo y motivo.');return DB::transaction(function()use($fromId,$toId,$amount,$at,$reason,$actor){$from=FinancialAccount::query()->where('is_active',true)->findOrFail($fromId);$to=FinancialAccount::query()->where('is_active',true)->findOrFail($toId);if($this->balances->execute($from->id)<$amount)throw new DomainException('La cuenta origen no tiene saldo suficiente.');$transfer=CashTransfer::create(['document_number'=>$this->numbers->execute('cash_transfer','TRC',$at),'from_account_id'=>$from->id,'to_account_id'=>$to->id,'amount'=>$amount,'transferred_at'=>$at,'reason'=>$reason,'created_by'=>$actor->id,'status'=>FinancialDocumentStatus::Confirmed]);$entry=$this->journal->execute(new JournalEntryData($at,"Traslado {$transfer->document_number}: {$reason}",$actor,[new JournalLineData($to->id,$amount,0,null,$reason),new JournalLineData($from->id,0,$amount,null,$reason)],$transfer));$transfer->update(['journal_entry_id'=>$entry->id]);return $transfer->fresh('journalEntry');});}}
